class FileCache
  def initialize(strategy = Mutex.new)
    @lock = strategy                     # Mutex, Monitor, Concurrent::ReadWriteLock
  end

  def find(path)
    @lock.synchronize { find_locked(path) }   # block-scoped acquire/release
  end
end
# re-entrant policy: Monitor.new   read/write policy: Concurrent::ReadWriteLock.new
